begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
grant analysis_writer to postgres with set true;
grant usage on schema extensions to analysis_writer;
insert into auth.users(id,is_anonymous) values
 ('ed100000-0000-4000-8000-000000000001',true),
 ('ed100000-0000-4000-8000-000000000002',true),
 ('ed100000-0000-4000-8000-000000000003',false);
insert into public.organizations(id,name) values('ed200000-0000-4000-8000-000000000002','Vision tenant B');
insert into public.stores(id,org_id,name) values('ed300000-0000-4000-8000-000000000002','ed200000-0000-4000-8000-000000000002','B');
insert into public.devices(id,org_id,store_id,auth_user_id,label) values
 ('ed400000-0000-4000-8000-000000000001','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','ed100000-0000-4000-8000-000000000001','A'),
 ('ed400000-0000-4000-8000-000000000002','ed200000-0000-4000-8000-000000000002','ed300000-0000-4000-8000-000000000002','ed100000-0000-4000-8000-000000000002','B');
insert into public.memberships(org_id,user_id,role) values('11111111-1111-4111-8111-111111111111','ed100000-0000-4000-8000-000000000003','owner');
create temporary table vision_context(key text primary key,value text);
grant select,insert,update,delete on vision_context to authenticated,analysis_writer;
insert into vision_context values
 ('disclaimer','AI observations describe visible cosmetic features in this photo, not a diagnosis or calibrated measurement. Lighting, makeup and camera quality can affect results. Photos are processed in memory by this app and are not saved or used for training. With your consent, a metadata-stripped photo is sent to OpenAI; provider retention may apply.'),
 ('vision','{"prompt_version":"visible-appearance-eval-v1","image_quality":"usable","quality_flags":[],"observed_features":{"visible_redness":"visible","visible_spots":"uncertain","visible_pores":"visible","visible_fine_lines":"visible","visible_flaking":"not_visible"}}');
create function pg_temp.write_vision(p_quality text default 'usable',p_vision jsonb default null) returns uuid language sql as $$
 select public.write_openai_analysis((select value::uuid from vision_context where key='session'),(select value::uuid from vision_context where key='session'),'gpt-4.1-mini-2025-04-14',p_quality,(select value from vision_context where key='disclaimer'),case when p_quality='not_provided' then p_vision else coalesce(p_vision,(select value::jsonb from vision_context where key='vision')) end)
$$;
select ok(not has_function_privilege('authenticated','public.write_openai_analysis(uuid,uuid,text,text,text,jsonb)','EXECUTE'),'Guests cannot forge photo observations');
select ok(not has_function_privilege('service_role','public.write_openai_analysis(uuid,uuid,text,text,text,jsonb)','EXECUTE'),'Service API cannot execute photo writer');
select ok(has_function_privilege('analysis_writer','public.write_openai_analysis(uuid,uuid,text,text,text,jsonb)','EXECUTE'),'Dedicated writer has exact photo writer');
select ok(not has_function_privilege('analysis_writer','public.claim_kiosk_vision_analysis(uuid)','EXECUTE'),'Writer cannot authorize an external request');
select ok(not has_table_privilege('analysis_writer','public.session_vision_attempts','SELECT,INSERT,UPDATE,DELETE'),'Writer has no direct attempt-table access');
select is((select count(*)::integer from pg_tables where schemaname='public' and tablename in ('session_vision_consents','session_vision_attempts','analysis_vision_outputs','analysis_vision_features','analysis_vision_quality_flags') and rowsecurity),5,'All photo tables enable RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
insert into vision_context select 'session',public.start_kiosk_session()::text;
select throws_ok($$select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',true)$$,'42501',null,'Main notice required before external consent');
select public.record_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-v1',true);
select throws_ok($$select public.record_vision_consent((select value::uuid from vision_context where key='session'),'old',true)$$,'22023',null,'Old photo notices fail closed');
select throws_ok($$select public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session'))$$,'42501',null,'Main consent never implies photo consent');
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',false);
select throws_ok($$select public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session'))$$,'42501',null,'Unticked external choice cannot claim');
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',true);
select throws_ok($$select public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session'))$$,'22023',null,'Claim requires completed preferences');
select public.save_answers((select value::uuid from vision_context where key='session'),'dry',array['dehydration'],'{}',false);
reset role;
set local role analysis_writer;
select throws_ok($$select pg_temp.write_vision()$$,'42501',null,'Photo output requires durable claim before transmission');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000002","is_anonymous":true}',true);
select throws_ok($$select public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session'))$$,'42501',null,'Another tenant cannot claim a photo');
select is((select count(*)::integer from public.session_vision_consents),0,'Another tenant cannot read photo consent');
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select is(public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session')),true,'First claim authorizes one attempt');
select is(public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session')),false,'Pending attempt cannot be retried after reload');
reset role;
set local role analysis_writer;
select throws_ok($$select pg_temp.write_vision('usable',(select value::jsonb||'{"diagnosis":"invented"}' from vision_context where key='vision'))$$,'22023',null,'Additional provider fields cannot enter storage');
select throws_ok($$select pg_temp.write_vision('usable',jsonb_set((select value::jsonb from vision_context where key='vision'),'{quality_flags}','["blur"]'))$$,'22023',null,'Usable quality cannot include limitations');
select throws_ok($$select pg_temp.write_vision('limited',jsonb_set((select value::jsonb from vision_context where key='vision'),'{image_quality}','"limited"'))$$,'22023',null,'Limited quality must identify limitations');
select throws_ok($$select pg_temp.write_vision('usable',jsonb_set((select value::jsonb from vision_context where key='vision'),'{observed_features,visible_redness}','"severe"'))$$,'22023',null,'Clinical grades cannot masquerade as visible categories');
insert into vision_context select 'analysis',pg_temp.write_vision()::text;
select is(pg_temp.write_vision()::text,(select value from vision_context where key='analysis'),'Completion reload is immutable and idempotent');
select throws_ok($$select public.persist_recommendations((select value::uuid from vision_context where key='session'),(select value::uuid from vision_context where key='analysis'),'a2786824-b258-5924-82b6-2d71465eb668','[{"variant_id":"33333333-3333-4333-8333-333333333333","score":3,"matched_ingredients":["Niacinamide"],"reasons":[{"concern":"uneven_tone","ingredient":"Niacinamide","relevance":3}]}]')$$,'22023',null,'Uncertain spots never add a recommendation concern');
insert into vision_context select 'run',public.persist_recommendations((select value::uuid from vision_context where key='session'),(select value::uuid from vision_context where key='analysis'),'a2786824-b258-5924-82b6-2d71465eb668','[{"variant_id":"33333333-3333-4333-8333-333333333334","score":3,"matched_ingredients":["Gluconolactone"],"reasons":[{"concern":"texture","ingredient":"Gluconolactone","relevance":3}]},{"variant_id":"33333333-3333-4333-8333-333333333335","score":3,"matched_ingredients":["Palmitoyl Tripeptide-1"],"reasons":[{"concern":"fine_lines","ingredient":"Palmitoyl Tripeptide-1","relevance":3}]},{"variant_id":"33333333-3333-4333-8333-333333333332","score":3,"matched_ingredients":["Glycerin"],"reasons":[{"concern":"dehydration","ingredient":"Glycerin","relevance":3}]}]')::text;
reset role;
select is((select count(*)::integer from public.analysis_vision_features where analysis_id=(select value::uuid from vision_context where key='analysis')),5,'Five features are normalized independent rows');
select is((select count(*)::integer from public.observations where analysis_id=(select value::uuid from vision_context where key='analysis')),0,'No numerical health or confidence scores are invented');
select is((select count(*)::integer from public.recommendation_items where run_id=(select value::uuid from vision_context where key='run')),3,'Usable visible pore/fine-line goals combine with the selected hydration goal');
select throws_ok($$insert into public.analysis_vision_features(org_id,analysis_id,feature,observed_value) values('ed200000-0000-4000-8000-000000000002',(select value::uuid from vision_context where key='analysis'),'visible_redness','visible')$$,'23503',null,'Composite foreign keys reject cross-tenant observations');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select is((select count(*)::integer from public.analysis_vision_features),0,'Staff cannot browse individual observations');
select is((select count(*)::integer from public.session_vision_attempts),0,'Staff cannot browse individual photo attempts');
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
select is(public.read_kiosk_session((select value::uuid from vision_context where key='session'))->'analysis'->>'mode','openai','Kiosk reload reconstructs OpenAI discriminator');
select is(public.read_kiosk_session((select value::uuid from vision_context where key='session'))->'analysis'->'vision'->'observed_features'->>'visible_redness','visible','Kiosk reads exact feature category');
select is(public.read_kiosk_session((select value::uuid from vision_context where key='session'))->'vision_consent'->>'notice_version','2026-10-openai-photo-v1','Separate photo notice persists');
select throws_ok($$select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',false)$$,'22023',null,'Completed outputs use finish and clear for withdrawal');
select public.finish_kiosk_session((select value::uuid from vision_context where key='session'));
reset role;
select is((select count(*)::integer from public.analysis_vision_outputs),0,'Finish cascades all photo output headers');
select is((select count(*)::integer from public.analysis_vision_features),0,'Finish cascades all observed features');
select is((select count(*)::integer from public.session_vision_consents where session_id=(select value::uuid from vision_context where key='session')),0,'Finish removes transient external consent');
select is((select count(*)::integer from public.session_vision_attempts where session_id=(select value::uuid from vision_context where key='session')),0,'Finish removes transient attempt records');
set local role analysis_writer;
select throws_ok($$select pg_temp.write_vision()$$,'42501',null,'Late external response cannot restore finished data');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000001","is_anonymous":true}',true);
update vision_context set value=public.start_kiosk_session()::text where key='session';
select public.record_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-v1',true);
select public.save_answers((select value::uuid from vision_context where key='session'),'dry',array['dehydration'],'{}',false);
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',true);
select is(public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session')),true,'New session can claim once');
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',false);
reset role;
set local role analysis_writer;
select throws_ok($$select pg_temp.write_vision()$$,'42501',null,'Withdrawal blocks in-flight completion');
reset role;
set local role authenticated;
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',true);
select is(public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session')),false,'Reaccepting never retries an invalidated attempt');
reset role;
set local role analysis_writer;
select throws_ok($$select pg_temp.write_vision()$$,'42501',null,'Reaccepting cannot resurrect an old in-flight response');
reset role;
set local role authenticated;
select public.finish_kiosk_session((select value::uuid from vision_context where key='session'));
update vision_context set value=public.start_kiosk_session()::text where key='session';
select public.record_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-v1',true);
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',false);
select public.save_answers((select value::uuid from vision_context where key='session'),'dry',array['dehydration'],'{}',false);
reset role;
set local role analysis_writer;
select lives_ok($$select pg_temp.write_vision('not_provided')$$,'Photo-free result operates after external choice declined');
reset role;
select is((select count(*)::integer from public.session_vision_attempts),0,'Photo-free path never creates an external attempt');
set local role authenticated;
select is(public.read_kiosk_session((select value::uuid from vision_context where key='session'))->'analysis'->'vision','null'::jsonb,'Photo-free reload has null vision');
select public.finish_kiosk_session((select value::uuid from vision_context where key='session'));
update vision_context set value=public.start_kiosk_session()::text where key='session';
select public.record_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-v1',true);
select public.record_vision_consent((select value::uuid from vision_context where key='session'),'2026-10-openai-photo-v1',true);
select public.save_answers((select value::uuid from vision_context where key='session'),'dry',array['dehydration'],'{}',false);
select is(public.claim_kiosk_vision_analysis((select value::uuid from vision_context where key='session')),true,'A fresh consented session can attempt a photo');
reset role;
set local role analysis_writer;
select lives_ok($$select pg_temp.write_vision('not_provided')$$,'Explicit photo-free completion is allowed after an attempted external request');
select lives_ok($$select pg_temp.write_vision()$$,'Late photo completion returns the existing immutable result');
reset role;
set local role authenticated;
select is(public.read_kiosk_session((select value::uuid from vision_context where key='session'))->'analysis'->'vision','null'::jsonb,'Late photo response never replaces explicit photo-free completion');
select public.finish_kiosk_session((select value::uuid from vision_context where key='session'));
reset role;
create function pg_temp.vision_cleanup_fixture() returns uuid language plpgsql as $$
declare v_session uuid; v_analysis uuid;
begin
  insert into public.kiosk_sessions(org_id,store_id,device_id,questionnaire_version_id)
    select '11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','ed400000-0000-4000-8000-000000000001',id from public.questionnaire_versions where active limit 1 returning id into v_session;
  insert into public.session_vision_consents(org_id,session_id,notice_version,accepted) values('11111111-1111-4111-8111-111111111111',v_session,'2026-10-openai-photo-v1',true);
  insert into public.session_vision_attempts(org_id,session_id) values('11111111-1111-4111-8111-111111111111',v_session);
  insert into public.analyses(org_id,session_id,request_id,mode,model_version,quality_status,disclaimer) values('11111111-1111-4111-8111-111111111111',v_session,v_session,'openai','gpt-4.1-mini-2025-04-14','limited',(select value from vision_context where key='disclaimer')) returning id into v_analysis;
  insert into public.analysis_vision_outputs(org_id,analysis_id,prompt_version) values('11111111-1111-4111-8111-111111111111',v_analysis,'visible-appearance-eval-v1');
  insert into public.analysis_vision_features(org_id,analysis_id,feature,observed_value) values('11111111-1111-4111-8111-111111111111',v_analysis,'visible_redness','uncertain');
  insert into public.analysis_vision_quality_flags(org_id,analysis_id,flag) values('11111111-1111-4111-8111-111111111111',v_analysis,'blur');
  return v_session;
end $$;
insert into vision_context select 'expired',pg_temp.vision_cleanup_fixture()::text;
update public.kiosk_sessions set last_activity_at=now()-interval '16 minutes' where id=(select value::uuid from vision_context where key='expired');
select private.cleanup_expired_data();
select is((select count(*)::integer from public.analysis_vision_outputs),0,'Scheduled expiry cascades photo headers');
select is((select count(*)::integer from public.analysis_vision_features),0,'Scheduled expiry cascades features');
select is((select count(*)::integer from public.analysis_vision_quality_flags),0,'Scheduled expiry cascades quality flags');
select is((select count(*)::integer from public.session_vision_consents where session_id=(select value::uuid from vision_context where key='expired')),0,'Scheduled expiry deletes optional photo consent');
select is((select count(*)::integer from public.session_vision_attempts where session_id=(select value::uuid from vision_context where key='expired')),0,'Scheduled expiry deletes photo claims');
insert into vision_context select 'revoked',pg_temp.vision_cleanup_fixture()::text;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"ed100000-0000-4000-8000-000000000003","is_anonymous":false}',true);
select public.revoke_device('ed400000-0000-4000-8000-000000000001');
reset role;
select is((select count(*)::integer from public.analysis_vision_outputs),0,'Device revocation cascades photo headers');
select is((select count(*)::integer from public.analysis_vision_features),0,'Device revocation cascades features');
select is((select count(*)::integer from public.analysis_vision_quality_flags),0,'Device revocation cascades quality flags');
select is((select count(*)::integer from public.session_vision_consents where session_id=(select value::uuid from vision_context where key='revoked')),0,'Device revocation deletes optional photo consent');
select is((select count(*)::integer from public.session_vision_attempts where session_id=(select value::uuid from vision_context where key='revoked')),0,'Device revocation deletes photo claims');
select * from finish();
rollback;
